const https = require('https');
const http = require('http');

const urls = [
  'https://cpp-book.softuni.bg',
  'https://js-book.softuni.bg',
  'https://python-book.softuni.bg',
  'https://csharp-book.softuni.bg',
  'https://introprogramming.info/intro-csharp-book/',
  'https://introprogramming.info/intro-java-book/',
  'https://nakov.com/books/inetjava/',
  'https://nakov.com/books/signatures/',
  'https://java-book.softuni.bg',
  'https://programirane.org/download-now/',
  'https://www.ctan.org/tex-archive/info/lshort/bulgarian',
  'http://www.devbg.org/dotnetbook/'
];

function fetch(u, redirects = 0) {
  return new Promise((resolve) => {
    const mod = u.startsWith('https') ? https : http;
    const req = mod.get(u, {
      headers: { 'User-Agent': 'Mozilla/5.0' },
      timeout: 15000
    }, (res) => {
      res.resume();
      if ([301, 302, 303, 307, 308].includes(res.statusCode) && res.headers.location && redirects < 5) {
        let next = res.headers.location;
        if (next.startsWith('/')) {
          next = new URL(next, u).toString();
        }
        resolve({ depth: redirects + 1, from: u, status: res.statusCode, to: next });
      } else {
        resolve({ depth: redirects, from: u, status: res.statusCode, to: null });
      }
    });
    req.on('timeout', () => { req.destroy(); resolve({ depth: redirects, from: u, status: 'TIMEOUT', to: null }); });
    req.on('error', (e) => resolve({ depth: redirects, from: u, status: 'ERR: ' + (e.code || e.message), to: null }));
  });
}

(async () => {
  for (const u of urls) {
    let cur = u;
    const chain = [];
    for (let i = 0; i < 6; i++) {
      const r = await fetch(cur, i);
      chain.push(r.status + (r.to ? ' -> ' + r.to : ''));
      if (!r.to || r.status === 200 || i >= 5) break;
      cur = r.to;
    }
    console.log(u);
    console.log('   ' + chain.join('\n   '));
  }
})();

